/**
 * Renders the provider navigation tabs based on keys in the allGames object.
 */
function renderProviderTabs() {
    const tabsContainer = document.getElementById('providerTabs');
    const providers = Object.keys(allGames);
    let htmlTabs = '';

    providers.forEach(provider => {
        const isActive = (provider === currentProvider) ? 'active' : '';
        const safeProviderName = provider.replace(/'/g, "\\'");
        
        let iconHtml = '';
        if (providerLogos[provider] && providerLogos[provider] !== "") {
            iconHtml = `<img src="${providerLogos[provider]}" class="tab-icon" alt="icon">`;
        }

        htmlTabs += `<button class="tab-btn ${isActive}" onclick="switchProvider('${safeProviderName}')">
                        ${iconHtml} ${provider}
                     </button>`;
    });
    
    tabsContainer.innerHTML = htmlTabs;
}

/**
 * Switches the active game provider and resets specific UI filters.
 */
function switchProvider(providerName) {
    currentProvider = providerName;
    isShowingFavorites = false;

    const favBtn = document.querySelectorAll('.filter-btn')[1];
    if(favBtn) favBtn.classList.remove('active');

    renderProviderTabs();
    lastRenderedBlock = -1; 
    generateRtpData();
}

