// --- TICKER FUNCTION (UPDATED LOGIC) ---
function startTicker() {
    setInterval(() => {
        const toast = document.getElementById('liveWinner');
        const text = document.getElementById('winnerText');

        // Ensure elements exist
        if (toast && text) {
            const randomWinner = winners[Math.floor(Math.random() * winners.length)];
            
            // Randomize amount (500k - 25m)
            const winAmount = Math.floor(Math.random() * 24500) + 500; 
            
            // Format number (e.g., 1.500)
            const formattedMoney = winAmount.toLocaleString('id-ID'); 

            // --- CHANGED HERE ---
            // Instead of "Name won IDR...", we use a visual separator "=> 💰 IDR"
            // This makes it look like a transaction log or status update.
            // Using slightly smaller font for the name so it fits better.
            
            text.innerHTML = `
                <span style="font-size:0.9em; font-weight:600; color:#fff;">${randomWinner}</span>
                <br>
                <span style="color:#00e676; font-weight:800;">💸 SUCCESS WD: IDR ${formattedMoney}.000</span>
            `;

            // Note: I added <br> to stack lines if your CSS allows height auto.
            // If it breaks layout, use this single line version instead:
            // text.innerHTML = `🏆 <strong>${randomWinner}</strong> ➡️ 💰 IDR ${formattedMoney}.000`;

            toast.classList.add('show');
            setTimeout(() => {
                toast.classList.remove('show');
            }, 4000);
        }
    }, 15000); 
}

/**
 * Generates a pseudo-random number based on a provided integer seed.
 */
function seededRandom(seed) {
    var t = seed += 0x6D2B79F5;
    t = Math.imul(t ^ t >>> 15, t | 1);
    t ^= t + Math.imul(t ^ t >>> 7, t | 61);
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
}

/**
 * Returns a hex color code based on the RTP percentage threshold.
 */
function getColor(percent) {
    if (percent >= 85) return '#00c853'; // Green
    if (percent >= 50) return '#ffab00'; // Yellow
    return '#d50000'; // Red
}

/**
 * Main rendering engine that calculates RTP values and builds the game grid HTML.
 */
function generateRtpData() {
    const gridContainer = document.getElementById('gameGrid');
    if(!gridContainer) return;
    
    let htmlBuffer = '';
    const now = new Date();
    const seconds = Math.floor(now.getTime() / 1000);
    const timeBlock = Math.floor(seconds / 1800);

    let displayList = [];

    if (isShowingFavorites) {
        Object.keys(allGames).forEach(prov => {
            allGames[prov].forEach(game => {
                if (favorites.includes(game.name)) {
                    displayList.push({ ...game, provider: prov });
                }
            });
        });

        if (displayList.length === 0) {
            htmlBuffer = `<div style="grid-column:1/-1; text-align:center; padding:40px; color:#888;">No favorite games yet.<br>Click the ❤️ icon on a game to save it.</div>`;
            gridContainer.innerHTML = htmlBuffer;
            return;
        }
    } else {
        if (!allGames[currentProvider]) allGames[currentProvider] = [];
        displayList = allGames[currentProvider].map(g => ({ ...g, provider: currentProvider }));
    }

    displayList.forEach((game, index) => {
        const nameSeed = game.name.length * 7;
        const uniqueSeed = timeBlock + (index * 99) + nameSeed;
        let randomVal = seededRandom(uniqueSeed);
        if (randomVal < 0) randomVal *= -1;
        game.rtp = Math.floor(randomVal * (98 - 20 + 1) + 20);
    });

    if (isSortedByRtp) {
        displayList.sort((a, b) => b.rtp - a.rtp);
    }

    displayList.forEach(game => {
        const color = getColor(game.rtp);
        const isFav = favorites.includes(game.name) ? 'is-active' : 'is-inactive';
        const favChar = isFav === 'is-active' ? '❤️' : '🤍';

        let badgeHtml = '';
        if (game.rtp >= 85) {
            badgeHtml = `<div class="gacor-badge" onclick="showPopup(event, '${game.name}', '${game.link}')">LIHAT POLA</div>`;
        }

        const reviewUrl = `#review-${encodeURIComponent(game.name)}`;

        htmlBuffer += `
            <div class="game-card">
                <div class="fav-icon ${isFav}" onclick="toggleFavorite('${game.name}')">${favChar}</div>
                ${badgeHtml}
                <a href="${game.link}" target="_blank" class="game-card-link">
                    <img src="${game.img}" alt="${game.name}" class="game-img" loading="lazy">
                </a>
                <div class="game-name">
                    <a href="${reviewUrl}" style="text-decoration:none; color:inherit;">${game.name}</a>
                </div>
                <div class="progress-bar">
                    <div class="progress-fill" style="width: ${game.rtp}%; background-color: ${color};"></div>
                </div>
                <span class="rtp-percent-text" style="color: ${color};">${game.rtp}%</span>
            </div>
        `;
    });

    gridContainer.innerHTML = htmlBuffer;
    lastRenderedBlock = timeBlock;
}

/**
 * Updates the countdown timer display based on a 30-minute rotation.
 */
function updateTimerDisplay(currentSeconds) {
    const duration = 1800; 
    const secondsInBlock = currentSeconds % duration;
    const secondsLeft = duration - secondsInBlock;

    const m = Math.floor(secondsLeft / 60);
    const s = Math.floor(secondsLeft % 60);
    const mStr = m < 10 ? '0' + m : m;
    const sStr = s < 10 ? '0' + s : s;

    const timerEl = document.getElementById('timerDisplay');
    if (timerEl) timerEl.innerText = `UPDATE: ${mStr}:${sStr}`;
}

/**
 * Logic to display the modal popup containing specific game patterns and "Hot Hours".
 */
function showPopup(event, gameName, gameLink) {
    event.preventDefault();
    event.stopPropagation();

    document.getElementById('modalGameName').innerText = gameName;
    const btn = document.getElementById('modalPlayBtn');
    if (btn) btn.href = gameLink || "#";

    const now = new Date();
    const seconds = Math.floor(now.getTime() / 1000);
    const timeBlock = Math.floor(seconds / 1800);

    let nameSeed = 0;
    for (let i = 0; i < gameName.length; i++) {
        nameSeed += gameName.charCodeAt(i);
    }

    const uniqueSeed = timeBlock + nameSeed + 555; 
    let randomVal = seededRandom(uniqueSeed);
    if (randomVal < 0) randomVal *= -1;

    const patternIdx = Math.floor(randomVal * patternsDB.length);
    const patterns = patternsDB[patternIdx];

    const hours = now.getHours();
    const minutes = now.getMinutes();
    let startStr, endStr;

    if (minutes < 30) {
        const h = hours < 10 ? '0' + hours : hours;
        startStr = `${h}:00`; endStr = `${h}:30`;
    } else {
        const h = hours < 10 ? '0' + hours : hours;
        const nextH = (hours + 1) % 24;
        const nextHStr = nextH < 10 ? '0' + nextH : nextH;
        startStr = `${h}:30`; endStr = `${nextHStr}:00`;
    }

    const hotHourStr = `${startStr} - ${endStr} WIB`;

    let listHtml = `
        <div class="pattern-item" style="color:#d50000; font-weight:bold; border-bottom:1px dashed #ddd; padding-bottom:8px; margin-bottom:10px;">
            <span class="pattern-icon">⏰</span> Jam Gacor: ${hotHourStr}
        </div>
    `;

    patterns.forEach(p => {
        listHtml += `<div class="pattern-item"><span class="pattern-icon">➤</span> ${p}</div>`;
    });

    document.getElementById('modalPatternList').innerHTML = listHtml;
    document.getElementById('patternModal').classList.add('active');
}

/**
 * Closes the modal popup if the user clicks outside the content.
 */
function closePopup(event) {
    if (event.target.id === 'patternModal') {
        document.getElementById('patternModal').classList.remove('active');
    }
}

/**
 * Forcefully closes the modal popup via the close button.
 */
function closePopupDirect() {
    document.getElementById('patternModal').classList.remove('active');
}

/**
 * Toggles the RTP sorting state and refreshes the game grid.
 */
function toggleSort() {
    isSortedByRtp = !isSortedByRtp;
    const btn = document.querySelector('.filter-btn span');
    if (btn) btn.innerHTML = isSortedByRtp ? '✅' : '🔃';

    const btnEl = document.querySelector('.filter-btn');
    isSortedByRtp ? btnEl.classList.add('active') : btnEl.classList.remove('active');

    generateRtpData();
}

/**
 * Adds or removes a game from the user's favorites list in local storage.
 */
function toggleFavorite(gameName) {
    if (favorites.includes(gameName)) {
        favorites = favorites.filter(n => n !== gameName);
    } else {
        favorites.push(gameName);
    }
    localStorage.setItem('favGames', JSON.stringify(favorites));
    generateRtpData(); 
}

/**
 * Filters the display to show only user-selected favorite games.
 */
function showFavorites() {
    isShowingFavorites = !isShowingFavorites;
    const tabs = document.querySelectorAll('.tab-btn');
    tabs.forEach(t => t.classList.remove('active'));

    const favBtn = document.querySelectorAll('.filter-btn')[1];
    isShowingFavorites ? favBtn.classList.add('active') : favBtn.classList.remove('active');

    generateRtpData();
}

/**
 * Initializes the UI theme based on user's local storage preference.
 */
function initTheme() {
    const savedTheme = localStorage.getItem('darkMode');
    const isDefaultDark = savedTheme === 'true' || savedTheme === null;

    if (isDefaultDark) {
        document.body.classList.add('dark-mode');
        if (savedTheme === null) localStorage.setItem('darkMode', 'true');
    } else {
        document.body.classList.remove('dark-mode');
    }
    updateThemeIcon();
}

/**
 * Toggles between Light and Dark mode and saves preference.
 */
function toggleTheme() {
    document.body.classList.toggle('dark-mode');
    const isDark = document.body.classList.contains('dark-mode');
    localStorage.setItem('darkMode', isDark);
    updateThemeIcon();
}

/**
 * Updates the theme toggle icon visibility based on the current mode.
 */
function updateThemeIcon() {
    const sunIcon = document.querySelector('.icon-sun');
    const moonIcon = document.querySelector('.icon-moon');
    const isDark = document.body.classList.contains('dark-mode');

    if (sunIcon && moonIcon) {
        sunIcon.style.display = isDark ? 'none' : 'block';
        moonIcon.style.display = isDark ? 'block' : 'none';
    }
}

/**
 * Main application loop to update timers and check for time-block changes.
 */
setInterval(function() {
    const now = new Date();
    const seconds = Math.floor(now.getTime() / 1000);
    const timeBlock = Math.floor(seconds / 1800);

    updateTimerDisplay(seconds);

    const input = document.getElementById('searchInput');
    const isSearching = input && input.offsetParent !== null && input.value.trim().length > 0;

    if (!isSearching && timeBlock !== lastRenderedBlock) {
        generateRtpData();
    }
}, 1000);

/**
 * Filters the global game list based on the user's search input.
 */
function searchGame() {
    const inputEl = document.getElementById('searchInput');
    const inputVal = inputEl.value.toLowerCase();
    const gridContainer = document.getElementById('gameGrid');
    const tabsContainer = document.querySelector('.tabs-wrapper');

    if (inputVal.length === 0) {
        if(tabsContainer) tabsContainer.style.display = 'block';
        generateRtpData();
        return;
    }

    if(tabsContainer) tabsContainer.style.display = 'none';

    let htmlBuffer = '';
    let foundCount = 0;
    
    Object.keys(allGames).forEach(providerKey => {
        allGames[providerKey].forEach((game) => {
            if (game.name.toLowerCase().includes(inputVal)) {
                foundCount++;
                let rtpValue = Math.floor(Math.random() * (98 - 40 + 1) + 40); 
                const color = getColor(rtpValue);

                let badgeHtml = '';
                if (rtpValue >= 85) {
                    badgeHtml = `<div class="gacor-badge" onclick="showPopup(event, '${game.name}', '${game.link}')">View Pattern</div>`;
                }

                htmlBuffer += `
                    <div class="game-card">
                        ${badgeHtml} 
                        <a href="${game.link}" target="_blank" class="game-card-link">
                            <img src="${game.img}" alt="${game.name}" class="game-img" loading="lazy">
                        </a>
                        <div class="game-name" style="flex-direction:column; gap:2px; height:auto; margin-bottom:8px;">
                            <span style="font-size:7px; color:#999; text-transform:uppercase;">${providerKey}</span>
                            <div>${game.name}</div>
                        </div>
                        <div class="progress-bar">
                            <div class="progress-fill" style="width: ${rtpValue}%; background-color: ${color};"></div>
                        </div>
                        <span class="rtp-percent-text" style="color: ${color};">${rtpValue}%</span>
                    </div>
                `;
            }
        });
    });

    if (foundCount === 0) {
        htmlBuffer = `
            <div style="grid-column: 1/-1; text-align:center; padding:40px 20px; color:#888;">
                <div style="font-size:2rem; margin-bottom:10px;">🔍</div>
                Game "<b>${inputVal}</b>" not found.
            </div>`;
    }

    gridContainer.innerHTML = htmlBuffer;
}

/* --- SECURITY --- */

initSecurity();

/**
 * Disables context menu (right-click) and developer keyboard shortcuts 
 * to discourage viewing source code.
 */
function initSecurity() {
    // Disable Right Click (Context Menu)
    document.addEventListener('contextmenu', function(event) {
        event.preventDefault();
    });

    // Disable Specific Key Combinations
    document.addEventListener('keydown', function(event) {
        
        // Block F12 (DevTools)
        if (event.key === 'F12' || event.keyCode === 123) {
            event.preventDefault();
            return false;
        }

        // Block Ctrl + U (View Source)
        if (event.ctrlKey && (event.key === 'u' || event.key === 'U')) {
            event.preventDefault();
            return false;
        }

        // Block Ctrl + Shift + I (DevTools Inspector)
        if (event.ctrlKey && event.shiftKey && (event.key === 'i' || event.key === 'I')) {
            event.preventDefault();
            return false;
        }

        // Block Ctrl + Shift + J (DevTools Console)
        if (event.ctrlKey && event.shiftKey && (event.key === 'j' || event.key === 'J')) {
            event.preventDefault();
            return false;
        }

        // Block Ctrl + S (Save Page)
        if (event.ctrlKey && (event.key === 's' || event.key === 'S')) {
            event.preventDefault();
            return false;
        }
    });
}